        public static long GetGlobalOffset(string global, int add = 0)
        {
            return GetGlobalNumbers(PrepareGlobal(global)) + add;
        }



        public static string PrepareGlobal(string global)
        {
            return Regex.Replace(global, @"\[.*?\]", string.Empty);
        }

        public static int GetGlobalNumbers(string global)
        {
            string[] gl = global.Split('.');
            int global_id = 0;
            foreach (string s in gl)
            {
                int.TryParse(Regex.Replace(s, "[^0-9]", ""), out int v);
                global_id += v;
            }
            return global_id;
        }
